import React from 'react';
import { render, screen } from '@testing-library/react';
import { Carousel } from './Carousel';
import { CarouselItem } from './components/CarouselItem';

describe('Carousel', () => {
  it.each`
    size    | numberOfSlides
    ${'xl'} | ${10}
    ${'lg'} | ${5}
    ${'md'} | ${4}
    ${'sm'} | ${3}
    ${'xs'} | ${2}
  `(
    'should group carousel items to have $numberOfSlides slides with 10 items',
    ({ size, numberOfSlides }) => {
      render(
        <Carousel size={size}>
          {Array.from({ length: 10 }, (_, index) => (
            <CarouselItem key={index}>{index}</CarouselItem>
          ))}
        </Carousel>
      );

      expect(screen.getAllByTestId('carousel-indicator')).toHaveLength(numberOfSlides);
    }
  );

  it('should not render arrows if showArrows is false', () => {
    render(
      <Carousel showArrows={false}>
        {Array.from({ length: 10 }, (_, index) => (
          <CarouselItem key={index}>{index}</CarouselItem>
        ))}
      </Carousel>
    );

    expect(screen.queryByTestId('carousel-action-prev')).toBeNull();
    expect(screen.queryByTestId('carousel-action-next')).toBeNull();
  });

  it('should not render arrows if number of items is not greater than items per view', () => {
    render(
      <Carousel size="md">
        {Array.from({ length: 2 }, (_, index) => (
          <CarouselItem key={index}>{index}</CarouselItem>
        ))}
      </Carousel>
    );

    expect(screen.queryByTestId('carousel-action-prev')).toBeNull();
    expect(screen.queryByTestId('carousel-action-next')).toBeNull();
  });
});
